INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Kundenbeziehungen > Kundenbeziehungen nach betrieblichen Grundsätzen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind Kundenbeziehungen nach betrieblichen Grundsätzen unabhängig von der Unternehmensstrategie zu gestalten?', 2, '[{"text": "Nein", "correct": true, "because": "Sie müssen mit der Strategie übereinstimmen"}, {"text": "Ja", "correct": false, "because": "Strategie gibt den Rahmen vor"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Kundenbeziehungen nach betrieblichen Grundsätzen ausschließlich auf Gewinnmaximierung ausgerichtet sein?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Kundenzufriedenheit und Langfristigkeit zählen"}, {"text": "Ja", "correct": false, "because": "Gewinn ist nicht alleiniger Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es nach betrieblichen Grundsätzen erforderlich, Kundenbeschwerden systematisch zu bearbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Systematik fördert Vertrauen und Verbesserung"}, {"text": "Nein", "correct": false, "because": "Unsystematische Bearbeitung schadet"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Kundenbeziehungen nach betrieblichen Grundsätzen ohne interne Kommunikation im Team aufrechterhalten werden?', 2, '[{"text": "Nein", "correct": true, "because": "Teamabstimmung ist essenziell für Konsistenz"}, {"text": "Ja", "correct": false, "because": "Fehlende Kommunikation führt zu Inkonsistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es nach betrieblichen Grundsätzen zulässig, Kundenanfragen ohne Rückmeldung unbeantwortet zu lassen?', 2, '[{"text": "Nein", "correct": true, "because": "Reaktionsfähigkeit ist ein Grundsatz"}, {"text": "Ja", "correct": false, "because": "Ignoranz schadet der Beziehung"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher betriebliche Grundsatz steht im Mittelpunkt der Kundenbeziehungen?', 2, '[{"text": "Kundenzufriedenheit", "correct": true, "because": "Sie sichert langfristigen Erfolg"}, {"text": "Kostensenkung", "correct": false, "because": "Wichtig, aber nicht zentral"}, {"text": "Produktivität", "correct": false, "because": "Interner Fokus, nicht kundenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Instrument wird nach betrieblichen Grundsätzen häufig eingesetzt, um Kundenbeziehungen zu optimieren?', 3, '[{"text": "Customer Relationship Management (CRM)", "correct": true, "because": "Systematisiert Kundeninteraktionen"}, {"text": "Produktentwicklungsplan", "correct": false, "because": "Technischer Fokus"}, {"text": "Mitarbeiterschulung", "correct": false, "because": "Indirekt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme entspricht am ehesten den betrieblichen Grundsätzen bei der Pflege von Kundenbeziehungen?', 2, '[{"text": "Regelmäßige Kundenbefragungen", "correct": true, "because": "Feedback fördert Verbesserung"}, {"text": "Aggressive Preisgestaltung", "correct": false, "because": "Kurzfristig, nicht nachhaltig"}, {"text": "Reduktion von Support", "correct": false, "because": "Schadet der Beziehung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt sollte nach betrieblichen Grundsätzen bei Kundenbeziehungen Priorität haben?', 2, '[{"text": "Langfristige Bindung", "correct": true, "because": "Stärkt Vertrauen und Umsatz"}, {"text": "Schnelle Vertragsabschlüsse", "correct": false, "because": "Kurzfristiger Fokus"}, {"text": "Minimierung von Kundenkontakt", "correct": false, "because": "Kontraproduktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Reaktion auf eine Kundenanfrage entspricht den betrieblichen Grundsätzen?', 2, '[{"text": "Schnelle, präzise Antwort", "correct": true, "because": "Zeigt Professionalität"}, {"text": "Verzögerte Bearbeitung", "correct": false, "because": "Schadet dem Vertrauen"}, {"text": "Standardisierte Absage", "correct": false, "because": "Ignoriert Kundenbedarf"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu Kundenbeziehungen nach betrieblichen Grundsätzen?', 4, '[{"text": "Kundenzufriedenheit", "correct": true, "because": "Kernziel der Beziehung"}, {"text": "Transparente Kommunikation", "correct": true, "because": "Fördert Vertrauen"}, {"text": "Systematische Dokumentation", "correct": true, "because": "Sichert Nachvollziehbarkeit"}, {"text": "Produktinnovation", "correct": false, "because": "Technisch, nicht beziehungsbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen Kundenbeziehungen nach betrieblichen Grundsätzen?', 3, '[{"text": "Regelmäßige Statusupdates", "correct": true, "because": "Hält Kunden informiert"}, {"text": "Proaktives Problemlösen", "correct": true, "because": "Zeigt Engagement"}, {"text": "Kundenkontaktmanagement", "correct": true, "because": "Optimiert Interaktionen"}, {"text": "Preiserhöhungen", "correct": false, "because": "Kann Beziehung belasten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ziele verfolgen Kundenbeziehungen nach betrieblichen Grundsätzen?', 4, '[{"text": "Kundenbindung", "correct": true, "because": "Langfristiger Nutzen"}, {"text": "Vertrauensaufbau", "correct": true, "because": "Basis für Kooperation"}, {"text": "Verbesserung der Servicequalität", "correct": true, "because": "Steigert Zufriedenheit"}, {"text": "Reduktion von Personal", "correct": false, "because": "Kein Kundenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozesse sind nach betrieblichen Grundsätzen bei Kundenbeziehungen wichtig?', 3, '[{"text": "Beschwerdeanagement", "correct": true, "because": "Löst Konflikte"}, {"text": "Kundenfeedback einholen", "correct": true, "because": "Fördert Optimierung"}, {"text": "Regelmäßige Kommunikation", "correct": true, "because": "Hält Beziehung aktiv"}, {"text": "Produktwerbung", "correct": false, "because": "Marketing, nicht Beziehung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressourcen werden nach betrieblichen Grundsätzen für Kundenbeziehungen genutzt?', 3, '[{"text": "CRM-Systeme", "correct": true, "because": "Strukturieren Daten"}, {"text": "Kommunikationstools", "correct": true, "because": "Erleichtern Kontakt"}, {"text": "Schulungen für Mitarbeiter", "correct": true, "because": "Verbessern Kompetenz"}, {"text": "Produktionsmaschinen", "correct": false, "because": "Technisch, nicht beziehungsrelevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Kundenbeziehungen nach betrieblichen Grundsätzen fördern die Kundenbindung. b) Sie erfordern keine interne Abstimmung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bindung ja, Abstimmung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nach betrieblichen Grundsätzen ist Kundenzufriedenheit ein Hauptziel. b) Kundenanfragen können ignoriert werden, wenn sie unwichtig erscheinen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zufriedenheit ja, Ignoranz nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) CRM-Systeme unterstützen Kundenbeziehungen nach betrieblichen Grundsätzen. b) Sie zielen ausschließlich auf Neukundengewinnung ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CRM ja, nicht nur Neukunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Regelmäßige Kommunikation ist ein betrieblicher Grundsatz. b) Kundenbeziehungen dürfen rein produktorientiert sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommunikation ja, Kundenfokus nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Beschwerdeanagement ist Teil der betrieblichen Grundsätze. b) Kundenfeedback ist optional und nicht essenziell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beschwerden ja, Feedback wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

